  risk_aml_rejectStd: { en: 'An honest customer\'s money is stuck, they complain, and they may leave the bank.', vi: 'Tiền của khách trung thực bị kẹt, họ khiếu nại và có thể rời bỏ ngân hàng.' },
  risk_aml_rejectExp: { en: 'Unwarranted restraint of funds, complaint escalation to the ombudsman and possible tipping-off exposure.', vi: 'Phong tỏa tiền không có căn cứ, khiếu nại leo thang tới cơ quan giải quyết và rủi ro tiết lộ thông tin (tipping-off).' },
  risk_aml_benefitStd: { en: 'Criminals are stopped while normal customers keep moving.', vi: 'Tội phạm bị chặn trong khi khách bình thường vẫn giao dịch suôn sẻ.' },
  risk_aml_benefitExp: { en: 'Accurate STR filing, low false-positive ratio and a defensible audit trail for the regulator.', vi: 'Lập STR chính xác, tỷ lệ cảnh báo giả thấp và hồ sơ kiểm toán vững chắc trước cơ quan quản lý.' },
  risk_dispute_approveStd: { en: 'The bank refunds money it cannot get back from the shop, so the bank pays.', vi: 'Ngân hàng hoàn tiền mà không đòi lại được từ cửa hàng, nên ngân hàng chịu lỗ.' },
  risk_dispute_approveExp: { en: 'Unrecoverable write-off: the acquirer represents with compelling evidence and the issuer absorbs the loss.', vi: 'Khoản lỗ không thu hồi được: ngân hàng thanh toán gửi lại bằng chứng hợp lệ và ngân hàng phát hành chịu lỗ.' },
  risk_dispute_rejectStd: { en: 'A customer who really was wronged loses money and trust.', vi: 'Khách hàng thật sự bị thiệt mất tiền và mất niềm tin.' },
  risk_dispute_rejectExp: { en: 'Scheme-rule breach on a valid claim, complaint escalation and conduct-risk findings.', vi: 'Vi phạm quy tắc tổ chức thẻ với khiếu nại hợp lệ, khiếu nại leo thang và phát hiện rủi ro hành vi.' },
  risk_dispute_benefitStd: { en: 'Fair outcomes: real victims get refunds, false claims do not.', vi: 'Kết quả công bằng: nạn nhân thật được hoàn tiền, khiếu nại sai thì không.' },
  risk_dispute_benefitExp: { en: 'Claims closed inside the SLA with correct liability shift and low chargeback loss ratio.', vi: 'Đóng khiếu nại trong SLA, chuyển trách nhiệm đúng và tỷ lệ lỗ chargeback thấp.' },
  risk_bnpl_approveStd: { en: 'The customer cannot keep up with the payments and falls into debt.', vi: 'Khách không theo kịp các kỳ trả và rơi vào nợ nần.' },
  risk_bnpl_approveExp: { en: 'Credit loss on default plus a responsible-lending breach for an unaffordable contract.', vi: 'Tổn thất tín dụng khi vỡ nợ, cộng thêm vi phạm cho vay có trách nhiệm vì hợp đồng vượt khả năng chi trả.' },
  risk_bnpl_rejectStd: { en: 'A good customer is turned away and buys somewhere else.', vi: 'Khách hàng tốt bị từ chối và mua hàng ở nơi khác.' },
  risk_bnpl_rejectExp: { en: 'Lost merchant fee and basket conversion; adverse-action notice required.', vi: 'Mất phí người bán và tỷ lệ chuyển đổi đơn hàng; phải gửi thông báo từ chối.' },
  risk_bnpl_benefitStd: { en: 'People borrow only what they can repay.', vi: 'Mọi người chỉ vay số tiền họ trả được.' },
  risk_bnpl_benefitExp: { en: 'Healthy approval rate with arrears kept inside risk appetite.', vi: 'Tỷ lệ duyệt lành mạnh, nợ quá hạn nằm trong khẩu vị rủi ro.' },
  risk_cashier_approveStd: { en: 'Fake notes enter the safe, or the drawer runs out mid-shift.', vi: 'Tiền giả vào két, hoặc ngăn kéo hết tiền giữa ca.' },
  risk_cashier_approveExp: { en: 'Counterfeit loss booked to the branch, or a till shortage and failed cash-limit control.', vi: 'Tổn thất tiền giả ghi nhận cho chi nhánh, hoặc thiếu quỹ quầy và vi phạm kiểm soát hạn mức tiền mặt.' },
  risk_cashier_rejectStd: { en: 'A customer with real money is sent home angry.', vi: 'Khách có tiền thật bị từ chối và ra về bực bội.' },
  risk_cashier_rejectExp: { en: 'Service failure on a valid cash transaction and a branch complaint.', vi: 'Lỗi dịch vụ với giao dịch tiền mặt hợp lệ và khiếu nại tại chi nhánh.' },
  risk_cashier_benefitStd: { en: 'The drawer balances at the end of the day.', vi: 'Ngăn kéo cân quỹ vào cuối ngày.' },
  risk_cashier_benefitExp: { en: 'Balanced till, clean CTR lodgement and intact vault liquidity.', vi: 'Quỹ quầy cân, nộp CTR đầy đủ và thanh khoản két được bảo toàn.' },
  risk_ekyc_approveStd: { en: 'A fake account is opened and used to move stolen money.', vi: 'Một tài khoản giả được mở và dùng để chuyển tiền ăn cắp.' },
  risk_ekyc_approveExp: { en: 'Mule account onboarded: KYC failure, downstream fraud losses and regulatory findings.', vi: 'Mở tài khoản la (mule): thất bại KYC, tổn thất gian lận về sau và kết luận thanh tra.' },
  risk_ekyc_rejectStd: { en: 'A real person cannot open their account and gives up.', vi: 'Một người thật không mở được tài khoản và bỏ cuộc.' },
  risk_ekyc_rejectExp: { en: 'Onboarding drop-off and acquisition cost wasted on a genuine applicant.', vi: 'Khách rời bỏ quy trình mở tài khoản và lãng phí chi phí thu hút một người thật.' },
  risk_ekyc_benefitStd: { en: 'Only real people get accounts.', vi: 'Chỉ người thật mới có tài khoản.' },
  risk_ekyc_benefitExp: { en: 'Low impostor acceptance with healthy straight-through onboarding.', vi: 'Tỷ lệ chấp nhận mạo danh thấp và mở tài khoản tự động thông suốt.' },
  risk_fds_approveStd: { en: 'A thief empties the account from a hacked phone.', vi: 'Kẻ gian rút sạch tài khoản từ chiếc điện thoại bị bẻ khóa.' },
  risk_fds_approveExp: { en: 'Account takeover loss and a spike in fraud-to-sales ratio; possible scheme monitoring programme.', vi: 'Tổn thất do chiếm đoạt tài khoản và tỷ lệ gian lận trên doanh số tăng vọt; có thể bị đưa vào chương trình giám sát.' },
  risk_fds_rejectStd: { en: 'A customer\'s card is blocked while they are at the till.', vi: 'Thẻ của khách bị chặn ngay khi đang thanh toán.' },
  risk_fds_rejectExp: { en: 'False decline: lost interchange and customer attrition.', vi: 'Từ chối nhầm: mất phí interchange và khách hàng rời bỏ.' },
  risk_fds_benefitStd: { en: 'Thieves are stopped before any money moves.', vi: 'Kẻ gian bị chặn trước khi tiền di chuyển.' },
  risk_fds_benefitExp: { en: 'Pre-authorisation fraud prevention with a low false-positive rate.', vi: 'Ngăn chặn gian lận trước cấp phép với tỷ lệ cảnh báo giả thấp.' },
  risk_swift_approveStd: { en: 'The money goes to the wrong place or bounces back days later.', vi: 'Tiền đến sai nơi hoặc bị trả về sau nhiều ngày.' },
  risk_swift_approveExp: { en: 'Rejected or misrouted pacs.008: investigation fees, FX revaluation loss and nostro break.', vi: 'Điện pacs.008 bị từ chối hoặc chuyển sai: phí tra soát, lỗ đánh giá lại tỷ giá và lệch nostro.' },
  risk_swift_rejectStd: { en: 'A correct payment is held up and the supplier is paid late.', vi: 'Một khoản thanh toán đúng bị giữ lại và nhà cung cấp nhận tiền muộn.' },
  risk_swift_rejectExp: { en: 'Missed cut-off, late-payment penalties for the client and SLA breach.', vi: 'Lỡ giờ chốt, khách bị phạt trả chậm và vi phạm SLA.' },
  risk_swift_benefitStd: { en: 'Money arrives first time, on time.', vi: 'Tiền đến đúng nơi, đúng hạn ngay lần đầu.' },
  risk_swift_benefitExp: { en: 'High straight-through processing rate and a reconciled nostro.', vi: 'Tỷ lệ xử lý tự động cao và tài khoản nostro được đối soát.' },

