  scene_task_dispute_2_triggerStd: { en: "The customer was charged for an online order but the merchant did not deliver within the promised time.", vi: "Khách mua hàng online đã bị trừ tiền nhưng Merchant không giao hàng quá SLA." },
  scene_task_dispute_2_triggerExp: { en: "Merchandise-not-received claim past the expected delivery date; issuer must check compelling evidence and merchant pre-arbitration response.", vi: "Khiếu nại không nhận được hàng đã quá hạn giao; ngân hàng phát hành cần kiểm tra bằng chứng và phản hồi của merchant trước trọng tài." },
  task_dispute_3_title: { en: "Stolen card (pacs.004 chargeback)", vi: "Thẻ bị đánh cắp (pacs.004 Chargeback)" },
  scene_task_dispute_3_story: { en: "{name} lost their card and is asking for {amount} in strange purchases back.", vi: "{name} bị mất thẻ và yêu cầu hoàn lại {amount} từ các giao dịch lạ." },
  scene_task_dispute_3_triggerStd: { en: "The cardholder reported the card lost and wants the unknown swipes refunded.", vi: "Chủ thẻ báo mất thẻ và yêu cầu đòi bồi hoàn các giao dịch quẹt lạ." },
  scene_task_dispute_3_triggerExp: { en: "Fraud claim: compare the card-status block timestamp with each authorisation timestamp before raising a pacs.004 PaymentReturn.", vi: "Khiếu nại gian lận: so sánh thời điểm khóa thẻ với thời điểm cấp phép từng giao dịch trước khi lập lệnh hoàn trả pacs.004." },
  task_bnpl_1_title: { en: "High debt-to-income (DTI)", vi: "Tỷ lệ nợ DTI cao (>50%)" },
  scene_task_bnpl_1_story: { en: "{name} wants to buy now and pay later for a {amount} purchase.", vi: "{name} muốn mua trước trả sau cho món hàng {amount}." },
  scene_task_bnpl_1_triggerStd: { en: "The customer applied for buy now, pay later, but their monthly repayments take more than 50% of their income.", vi: "Khách đăng ký mua trước trả sau nhưng tổng nghĩa vụ trả nợ hàng tháng chiếm trên 50% thu nhập." },
  scene_task_bnpl_1_triggerExp: { en: "Affordability assessment: debt-to-income ratio from bureau and declared income breaches the responsible-lending cap.", vi: "Đánh giá khả năng chi trả: tỷ lệ nợ trên thu nhập từ dữ liệu tín dụng và thu nhập khai báo vượt trần cho vay có trách nhiệm." },
  task_bnpl_2_title: { en: "Late Pay-in-4 history", vi: "Lịch sử Pay-in-4 trễ hạn" },
  scene_task_bnpl_2_story: { en: "{name} is asking for a new {amount} instalment plan.", vi: "{name} đang xin một gói trả góp mới {amount}." },
  scene_task_bnpl_2_triggerStd: { en: "The customer had instalment plans paid more than 15 days late in earlier periods.", vi: "Khách có hợp đồng trả góp bị chậm thanh toán hơn 15 ngày ở các kỳ trước." },
  scene_task_bnpl_2_triggerExp: { en: "Internal repayment history shows Pay-in-4 delinquencies above the 15 DPD threshold; limit-increase eligibility check.", vi: "Lịch sử trả nợ nội bộ cho thấy khoản Pay-in-4 quá hạn trên 15 ngày; kiểm tra điều kiện tăng hạn mức." },
  task_bnpl_3_title: { en: "New customer, high limit ($3k)", vi: "Khách mới xin hạn mức cao ($3k)" },
  scene_task_bnpl_3_story: { en: "{name} wants {amount} in instalments for new tech gear.", vi: "{name} muốn trả góp {amount} để mua đồ công nghệ." },
  scene_task_bnpl_3_triggerStd: { en: "An account opened only days ago is asking to approve a $3,000 instalment plan.", vi: "Tài khoản tạo 3 ngày nhưng xin duyệt khoản trả góp $3,000 mua đồ công nghệ." },
  scene_task_bnpl_3_triggerExp: { en: "Thin-file applicant: account tenure below the seasoning period, so the new-customer exposure cap applies.", vi: "Khách hàng ít dữ liệu: thời gian mở tài khoản chưa đủ kỳ theo dõi, áp dụng trần hạn mức cho khách mới." },
  task_cashier_1_title: { en: "Large cash ≥ $10k (CTR)", vi: "Giao dịch tiền mặt lớn >= $10k (Báo cáo CTR)" },
