  scene_task_cashier_2_triggerExp: { en: "Banknote authentication (serial blacklist and polymer substrate checks) failed on one or more notes in the lodgement.", vi: "Kiểm tra xác thực tiền (danh sách seri và chất liệu polymer) thất bại trên một hoặc nhiều tờ trong xấp nộp." },
  task_cashier_3_title: { en: "Withdrawal over till cash", vi: "Rút tiền vượt quỹ quầy (Till Cash Exceeded)" },
