  scene_task_cashier_3_triggerExp: { en: "Requested cash-out exceeds the teller drawer limit; dual-control vault replenishment required before payout.", vi: "Số tiền rút vượt hạn mức ngăn kéo giao dịch viên; cần tiếp quỹ từ kho theo nguyên tắc kiểm soát kép trước khi chi." },
  task_swift_1_title: { en: "Missing ISO 20022 fields", vi: "Thiếu trường dữ liệu ISO 20022" },
  scene_task_swift_1_story: { en: "{name} is receiving a {amount} international transfer.", vi: "{name} đang nhận một khoản chuyển tiền quốc tế {amount}." },
