  scene_task_swift_2_triggerExp: { en: "Liquidity check: settlement amount exceeds the available nostro position at the correspondent; queue pending treasury funding.", vi: "Kiểm tra thanh khoản: số tiền thanh toán vượt số dư khả dụng của nostro tại ngân hàng đại lý; chờ bộ phận nguồn vốn cấp vốn." },
  task_swift_3_title: { en: "Sanctioned correspondent bank", vi: "Ngân hàng Đại lý bị cấm vận" },
