  challengeHint: { en: "Time-Attack Challenge. Review as many cases as you can in {min} minutes. +{base} XP per correct call, up to +{bonus} XP speed bonus within {window} seconds, −{penalty} XP per error.", vi: "Thử thách tính giờ. Xử lý càng nhiều hồ sơ càng tốt trong {min} phút. +{base} XP cho mỗi quyết định đúng, thưởng tốc độ tối đa +{bonus} XP nếu xong trong {window} giây, −{penalty} XP cho mỗi lỗi." },
  challengeTimerLabel: { en: "Shift time left", vi: "Thời gian ca còn lại" },
  challengeTitle: { en: "⏱️ Time-Attack shift", vi: "⏱️ Ca thử thách tính giờ" },
  challengeScore: { en: "{xp} XP", vi: "{xp} điểm XP" },
  challengeLive: { en: "{n} reviewed · {acc} accurate", vi: "Đã xử lý {n} · chính xác {acc}" },
  challengeRules: { en: "+{base} correct · up to +{bonus} if under {window}s · −{penalty} error", vi: "+{base} khi đúng · tối đa +{bonus} nếu dưới {window} giây · −{penalty} khi sai" },
  overlayPoints: { en: "{pts} XP", vi: "{pts} điểm XP" },
  overlayBonus: { en: "incl. +{bonus} speed bonus", vi: "gồm +{bonus} thưởng tốc độ" },
  scorecardTitle: { en: "🏁 End of shift", vi: "🏁 Kết thúc ca" },
  scorecardSubtitle: { en: "Time is up. Here is how your {min}-minute shift went.", vi: "Hết giờ. Đây là kết quả ca {min} phút của bạn." },
  scReviewed: { en: "Cases reviewed", vi: "Số hồ sơ đã xử lý" },
